//! C++ SDK header generation.
//!
//! Turns dumper output (interfaces, schema classes, resolved offsets) into the
//! headers the C++ payload consumes. The renderers are pure string functions so
//! they can be fixture-tested without a game process; [`write_sdk`] wires them
//! to the filesystem.
//!
//! Output layout (under a target directory):
//!
//! ```text
//! interfaces.hpp      CreateInterface registrations
//! offsets.hpp         resolved RVAs (signature/schema/manual)
//! schemas.hpp         aggregator that includes the per-module headers
//! schemas/<mod>.hpp   per-module class/field metadata
//! ```
//!
//! Generated constants follow the project's naming conventions (see ADR-0010):
//! `PascalCase` types, `SCREAMING_SNAKE_CASE` constants, `snake_case` functions.

use std::fmt::Write as _;
use std::path::{Path, PathBuf};

use anyhow::{Context, Result};

use crate::analysis::{Offset, OffsetSource};
use crate::interfaces::Interface;
use crate::schema::SchemaClass;

const BANNER: &str = "\
// Generated by cs2-dumper — do not edit by hand.
// Re-run the dumper with --gen to regenerate (see payload/sdk/README.md).
";

/// Inputs for one SDK generation pass. Any slice may be empty.
#[derive(Debug, Default, Clone, Copy)]
pub struct SdkInputs<'a> {
    pub interfaces: &'a [Interface],
    pub schema: &'a [SchemaClass],
    pub offsets: &'a [Offset],
}

/// Write the full SDK under `dir`, returning the paths written.
pub fn write_sdk(dir: &Path, inputs: &SdkInputs<'_>) -> Result<Vec<PathBuf>> {
    std::fs::create_dir_all(dir).with_context(|| format!("creating {}", dir.display()))?;
    let mut written = Vec::new();

    let schemas_dir = dir.join("schemas");
    std::fs::create_dir_all(&schemas_dir)
        .with_context(|| format!("creating {}", schemas_dir.display()))?;

    let mut write = |path: PathBuf, contents: String| -> Result<()> {
        std::fs::write(&path, contents).with_context(|| format!("writing {}", path.display()))?;
        written.push(path);
        Ok(())
    };

    write(
        dir.join("interfaces.hpp"),
        render_interfaces(inputs.interfaces),
    )?;
    write(dir.join("offsets.hpp"), render_offsets(inputs.offsets))?;

    // Group schema classes by module, preserving first-seen order.
    let mut modules: Vec<(String, Vec<&SchemaClass>)> = Vec::new();
    for class in inputs.schema {
        match modules.iter_mut().find(|(name, _)| *name == class.module) {
            Some((_, classes)) => classes.push(class),
            None => modules.push((class.module.clone(), vec![class])),
        }
    }

    let mut module_slugs = Vec::new();
    for (module, classes) in &modules {
        let slug = unique_slug(module, &module_slugs);
        module_slugs.push(slug.clone());
        write(
            schemas_dir.join(format!("{slug}.hpp")),
            render_schema_module(module, classes),
        )?;
    }

    write(
        dir.join("schemas.hpp"),
        render_schemas_aggregator(&module_slugs),
    )?;

    Ok(written)
}

/// Render `interfaces.hpp`.
pub fn render_interfaces(items: &[Interface]) -> String {
    const PROLOGUE: &str = r#"#pragma once

// CreateInterface registration descriptors found in the target build.
// `node_rva` is the InterfaceReg node; `create_rva` is its create() function.

#include <array>
#include <cstdint>
#include <string_view>

namespace cs2::sdk {

struct InterfaceInfo {
  std::string_view name;    // our identifier
  std::string_view target;  // original target name (CreateInterface key)
  std::uint32_t node_rva;
  std::uint32_t create_rva;
};

"#;
    const EPILOGUE: &str = r#"
// Look up a registration by our identifier; returns nullptr if absent.
[[nodiscard]] inline const InterfaceInfo* find_interface(std::string_view name) noexcept {
  for (const InterfaceInfo& info : INTERFACES) {
    if (info.name == name) return &info;
  }
  return nullptr;
}

// Look up a registration by the original target name.
[[nodiscard]] inline const InterfaceInfo* find_interface_by_target(std::string_view target) noexcept {
  for (const InterfaceInfo& info : INTERFACES) {
    if (info.target == target) return &info;
  }
  return nullptr;
}

}  // namespace cs2::sdk
"#;

    let mut s = String::from(BANNER);
    s.push_str(PROLOGUE);
    let _ = writeln!(
        s,
        "inline constexpr std::array<InterfaceInfo, {}> INTERFACES = {{{{",
        items.len()
    );
    for it in items {
        let _ = writeln!(
            s,
            "  {{ {}, {}, 0x{:x}, 0x{:x} }},",
            cpp_string(&it.name),
            cpp_string(&it.target),
            it.rva,
            it.create_rva
        );
    }
    s.push_str("}};\n");
    s.push_str(EPILOGUE);
    s
}

/// Render `offsets.hpp`.
pub fn render_offsets(items: &[Offset]) -> String {
    const PROLOGUE: &str = r#"#pragma once

// Resolved RVAs for the target build. `source` records how each was obtained;
// RVAs are relative to the owning module's image base.

#include <array>
#include <cstdint>
#include <string_view>

namespace cs2::sdk {

enum class OffsetSource { signature, schema, manual };

struct OffsetInfo {
  std::string_view name;
  std::string_view module;
  std::uint32_t rva;
  OffsetSource source;
};

"#;
    const EPILOGUE: &str = r#"
// Look up an offset by name; returns nullptr if absent.
[[nodiscard]] inline const OffsetInfo* find_offset(std::string_view name) noexcept {
  for (const OffsetInfo& info : OFFSETS) {
    if (info.name == name) return &info;
  }
  return nullptr;
}

}  // namespace cs2::sdk
"#;

    let mut s = String::from(BANNER);
    s.push_str(PROLOGUE);

    // Emit a named constant per offset. Names are expected to be unique; if a
    // duplicate slips through, the later entry is skipped and reported in a
    // trailing comment so the build never sees a redefinition.
    let mut used = std::collections::BTreeSet::new();
    let mut duplicates = Vec::new();
    for off in items {
        let ident = format!("{}_RVA", sanitize_upper(&off.name));
        if used.insert(ident.clone()) {
            let _ = writeln!(
                s,
                "inline constexpr std::uint32_t {ident} = 0x{:x};  // {}",
                off.rva, off.module
            );
        } else {
            duplicates.push(off.name.clone());
        }
    }
    if !duplicates.is_empty() {
        let _ = writeln!(
            s,
            "// skipped duplicate offset names: {}",
            duplicates.join(", ")
        );
    }
    s.push('\n');

    let _ = writeln!(
        s,
        "inline constexpr std::array<OffsetInfo, {}> OFFSETS = {{{{",
        items.len()
    );
    for off in items {
        let _ = writeln!(
            s,
            "  {{ {}, {}, 0x{:x}, OffsetSource::{} }},",
            cpp_string(&off.name),
            cpp_string(&off.module),
            off.rva,
            source_variant(off.source)
        );
    }
    s.push_str("}};\n");
    s.push_str(EPILOGUE);
    s
}

/// Render one `schemas/<module>.hpp`.
pub fn render_schema_module(module: &str, classes: &[&SchemaClass]) -> String {
    let slug = sanitize_slug(module);
    const PROLOGUE: &str = r#"#pragma once

// Schema classes and fields for one module.

#include <cstdint>
#include <span>
#include <string_view>

"#;
    const TYPES: &str = r#"
struct FieldInfo {
  std::string_view name;    // our identifier
  std::string_view type;    // rewritten type display
  std::uint32_t offset;
  std::string_view target;  // original target field name
};

struct ClassInfo {
  std::string_view name;         // our type name
  std::string_view target_name;  // original target class name
  std::uint32_t size;
  std::span<const FieldInfo> fields;
};

"#;
    const EPILOGUE: &str = r#"
// Look up a class by our name; returns nullptr if absent.
[[nodiscard]] inline const ClassInfo* find_class(std::string_view name) noexcept {
  for (const ClassInfo& info : CLASSES) {
    if (info.name == name) return &info;
  }
  return nullptr;
}

// Look up a class by the original target name.
[[nodiscard]] inline const ClassInfo* find_class_by_target(std::string_view target) noexcept {
  for (const ClassInfo& info : CLASSES) {
    if (info.target_name == target) return &info;
  }
  return nullptr;
}

// Offset of a named field, or 0 if the class/field is absent.
[[nodiscard]] inline std::uint32_t field_offset(std::string_view class_name,
                                                std::string_view field_name) noexcept {
  const ClassInfo* cls = find_class(class_name);
  if (cls == nullptr) return 0;
  for (const FieldInfo& field : cls->fields) {
    if (field.name == field_name) return field.offset;
  }
  return 0;
}

// Offset of a field by the original target names.
[[nodiscard]] inline std::uint32_t field_offset_by_target(std::string_view class_target,
                                                          std::string_view field_target) noexcept {
  const ClassInfo* cls = find_class_by_target(class_target);
  if (cls == nullptr) return 0;
  for (const FieldInfo& field : cls->fields) {
    if (field.target == field_target) return field.offset;
  }
  return 0;
}
"#;

    let mut s = String::from(BANNER);
    s.push_str(PROLOGUE);
    let _ = writeln!(s, "namespace cs2::sdk::schemas::{slug} {{");
    let _ = writeln!(
        s,
        "\ninline constexpr std::string_view MODULE = {};",
        cpp_string(module)
    );
    s.push_str(TYPES);

    // Field arrays first so the CLASSES initializer can reference them.
    let mut array_names: Vec<Option<String>> = Vec::new();
    let mut used: Vec<String> = Vec::new();
    for class in classes {
        if class.fields.is_empty() {
            array_names.push(None);
            continue;
        }
        let name = unique_slug(&format!("{}_fields", class.name), &used);
        used.push(name.clone());
        let _ = writeln!(s, "inline constexpr FieldInfo {name}[] = {{");
        for field in &class.fields {
            let _ = writeln!(
                s,
                "  {{ {}, {}, 0x{:x}, {} }},",
                cpp_string(&field.name),
                cpp_string(&field.type_name),
                field.offset,
                cpp_string(&field.target_name)
            );
        }
        s.push_str("};\n\n");
        array_names.push(Some(name));
    }

    s.push_str("inline constexpr ClassInfo CLASSES[] = {\n");
    for (class, array) in classes.iter().zip(&array_names) {
        let fields = match array {
            Some(name) => name.as_str(),
            None => "std::span<const FieldInfo>{}",
        };
        let _ = writeln!(
            s,
            "  {{ {}, {}, 0x{:x}, {} }},",
            cpp_string(&class.name),
            cpp_string(&class.target_name),
            class.size,
            fields
        );
    }
    s.push_str("};\n");
    s.push_str(EPILOGUE);
    let _ = writeln!(s, "\n}}  // namespace cs2::sdk::schemas::{slug}");
    s
}

/// Render the `schemas.hpp` aggregator that includes every module header.
pub fn render_schemas_aggregator(module_slugs: &[String]) -> String {
    let mut s = String::from(BANNER);
    s.push_str(
        "#pragma once\n\n\
         // Umbrella header for the generated per-module schema headers.\n\n",
    );
    for slug in module_slugs {
        let _ = writeln!(s, "#include \"schemas/{slug}.hpp\"");
    }
    if module_slugs.is_empty() {
        s.push_str("// (no schema modules were dumped)\n");
    }
    s
}

fn source_variant(source: OffsetSource) -> &'static str {
    use OffsetSource::*;
    match source {
        Signature => "signature",
        Schema => "schema",
        Manual => "manual",
    }
}

/// A valid lowercase C++ identifier derived from `s`.
fn sanitize_slug(s: &str) -> String {
    sanitize(s, false)
}

/// A valid uppercase C++ identifier derived from `s`.
fn sanitize_upper(s: &str) -> String {
    sanitize(s, true)
}

fn sanitize(s: &str, upper: bool) -> String {
    let chars: Vec<char> = s.chars().collect();
    let mut out = String::with_capacity(s.len() + 4);
    let mut prev: Option<char> = None;
    for (i, &c) in chars.iter().enumerate() {
        // Insert `_` at CamelCase boundaries: lower/digit -> Upper, or the end
        // of an acronym run (Upper -> Upper -> lower).
        let separated = match prev {
            Some(p) if c.is_ascii_uppercase() => {
                p.is_ascii_lowercase()
                    || p.is_ascii_digit()
                    || (p.is_ascii_uppercase()
                        && chars.get(i + 1).is_some_and(|n| n.is_ascii_lowercase()))
            }
            _ => false,
        };
        if separated && !out.is_empty() && !out.ends_with('_') {
            out.push('_');
        }
        if c.is_ascii_alphanumeric() {
            out.push(if upper {
                c.to_ascii_uppercase()
            } else {
                c.to_ascii_lowercase()
            });
        } else if !out.ends_with('_') {
            out.push('_');
        }
        prev = Some(c);
    }
    if out.is_empty() || out.as_bytes()[0].is_ascii_digit() {
        out.insert(0, '_');
    }
    out
}

/// Return a valid identifier for `s`, suffixing `_2`, `_3`, … on collision.
fn unique_slug(s: &str, used: &[String]) -> String {
    let base = sanitize_slug(s);
    if !used.contains(&base) {
        return base;
    }
    for n in 2.. {
        let candidate = format!("{base}_{n}");
        if !used.contains(&candidate) {
            return candidate;
        }
    }
    unreachable!()
}

/// Quote `s` as a C++ string literal, escaping `\`, `"` and non-printables.
/// Non-printable bytes use 3-digit octal escapes, which cannot merge with a
/// following hex digit.
fn cpp_string(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('"');
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '"' => out.push_str("\\\""),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if c.is_ascii_graphic() || c == ' ' => out.push(c),
            c if (c as u32) <= 0xff => {
                let _ = write!(out, "\\{:03o}", c as u32);
            }
            c => {
                let _ = write!(out, "\\u{:04x}", c as u32);
            }
        }
    }
    out.push('"');
    out
}
